# tour.py -- generated by make_tour.py. Each screen reports what you do in the yellow line at the bottom.
import math
from Runtime import *

SCREENS = ['master_basic', 'master_inputs', 'master_graphics', 'master_keyboards', 'master_choices', 'master_tree', 'master_displays']
cur = 0


def say(t):
    globals()["st_" + SCREENS[cur]].text = t


def go(i):
    global cur
    cur = i % len(SCREENS)
    Screen(SCREENS[cur])
    say(SCREENS[cur])


def prev_master_basic_click():
    go(-1)


def next_master_basic_click():
    go(1)


def prev_master_inputs_click():
    go(0)


def next_master_inputs_click():
    go(2)


def prev_master_graphics_click():
    go(1)


def next_master_graphics_click():
    go(3)


def prev_master_keyboards_click():
    go(2)


def next_master_keyboards_click():
    go(4)


def prev_master_choices_click():
    go(3)


def next_master_choices_click():
    go(5)


def prev_master_tree_click():
    go(4)


def next_master_tree_click():
    go(6)


def prev_master_displays_click():
    go(5)


def next_master_displays_click():
    go(7)


count = 0
phase = 0.0


def button1_click():
    global count
    count += 1
    label1.text = "Tapped %d" % count
    memo1.text = memo1.text + "\nTap %d" % count
    say("button1 click %d" % count)


def button2_click():
    a = message("Delete everything?", "Yes", "No")
    say("answer: " + a)


def button3_click():
    t = keyboard2.show()
    if t is not None:
        memo1.text = memo1.text + "\n" + t
    say("typed: " + (t if t is not None else "(cancelled)"))


def button4_click():
    t = keyboard1.show()
    if t is not None:
        memo2.text = t
    say("keyboard: " + (t if t is not None else "(cancelled)"))


def memo2_changed(text):
    say("memo2: %d chars" % len(text))


def switch1_changed(v):
    say("switch1 = %s" % v)


def checkbox1_changed(v):
    say("checkbox1 = %s" % v)


def slider1_changing(v):
    progressbar1.value = v
    say("slider1 moving %s" % v)


def slider1_changed(v):
    progressbar1.value = v
    say("slider1 set %s" % v)


def slider2_changing(v):
    progressbar2.value = v
    say("slider2 moving %s" % v)


def slider2_changed(v):
    progressbar2.value = v
    say("slider2 set %s" % v)


def keyboard1_enter(text):
    say("keyboard1: %d chars" % len(text))


def keyboard2_enter(text):
    say("keyboard2: " + text)


def choice1_changed(i):
    say("choice1 = %s" % choice1.items[i])


def choice2_changed(i):
    say("choice2 = %s" % choice2.items[i])


def choice3_changed(i):
    say("choice3 = %s" % choice3.items[i])


def tree1_selected(path):
    say(path)


def stepper1_changed(v):
    gauge1.value = v
    barchart1.set(4, v * 10)
    say("stepper1 = %s" % v)


def tick():
    global phase
    phase += 0.3
    waveform1.add(50 + 40 * math.sin(phase))


every(300, tick)
go(0)
run()
